      arrowD: `M${x1.toFixed(1)} ${y1.toFixed(1)} C ${(x1 + 6).toFixed(1)} ${(y2 + (y1 - y2) * .35).toFixed(1)}, ${(x2 - 24).toFixed(1)} ${y2.toFixed(1)}, ${x2.toFixed(1)} ${y2.toFixed(1)}`, arrowOp: tr > tl ? .9 : 0,
      lArt: isFd ? 'assets/art/bank.svg' : 'assets/art/flat.svg', iconS: `bottom:${(topL + 4).toFixed(0)}px`,
      rigS: `bottom:${(topR + 20).toFixed(0)}px;transform:translateX(-50%) scale(${fit.toFixed(3)});transform-origin:50% 100%`, tagS: `bottom:${(topR + 2).toFixed(0)}px`,
      swpCls: 'mcl-swp' + (S.swp ? '' : ' off'), swpOn: S.swp,
      toggleSwp: () => this.setState(s => { const on = !s.swp, k = s.mode === 'fd' ? 'P' : 'price'; return on && s[k] < SWP_MIN ? { swp: on, [k]: SWP_MIN, exact: { ...s.exact, [k]: true }, hint: `A monthly income needs ${this.words(SWP_MIN)} or more — set to ${this.words(SWP_MIN)}`, bad: true } : { swp: on }; }),
      prevV: () => this.setState({ villa: villas[(vi + villas.length - 1) % villas.length].key }), nextV: () => this.setState({ villa: villas[(vi + 1) % villas.length].key }),
      villaS: `transform:scale(${(.85 + vi * .12).toFixed(2)})`, coinS: `opacity:${S.swp ? 1 : .35};transition:opacity .3s`,
      tagName: villa.name, tagRate: (irr == null ? vRate : irr).toFixed(1) + '% a yr', tagYrs: isFd ? 'last ' + S.yrs + ' yrs' : 'since ' + bought,
      totL: this.fmt(tl), totR: this.fmt(tr),
      boxLS: `height:${(lp + lv).toFixed(1)}px`, segLpS: `height:${lp.toFixed(1)}px`, segLvS: `height:${lv.toFixed(1)}px`, hasPaidL: L.paid > 0,
      boxRS: `height:${(rp + rv).toFixed(1)}px`, segRpS: `height:${rp.toFixed(1)}px`, segRvS: `height:${rv.toFixed(1)}px`, hasPaidR: S.swp && R.paid > 0,
      paidLabelL: L.paidLabel, valLabelL: L.valLabel, paidL: this.fmt(Math.max(0, L.paid)), valL: this.fmt(L.val),
      paidLabelR: isFd ? 'Paid out' : 'Rent paid', paidR: this.fmt(R.paid), valR: this.fmt(R.val),
