      amt: this.show(S, this.fields(S)[0]), bandCls: 'card' + (typing('P') ? ' typing' : ''), typingP: typing('P'), notTypingP: !typing('P'), editP: () => this.startEdit('P'),
      // Real estate: the question line + the four cards
