      cards: isFd ? [] : this.fields(S).map(q => ({ key: q.key, label: q.label, value: this.show(S, q), long: this.show(S, q).length > 11, on: S.active === q.key ? 'true' : 'false', typing: typing(q.key), show: !typing(q.key), aria: q.label + ', type it',
        cls: 'mcl-card' + (S.active === q.key ? ' on' : '') + (typing(q.key) ? ' typing' : ''), bcls: 'mono' + (this.show(S, q).length > 11 ? ' long' : ''),
        pick: () => { if (ed && ed.key === q.key) return; if (S.active === q.key && !ed) this.startEdit(q.key); else this.setState({ active: q.key, edit: null }); } })),
      // the shared ruler and its buttons follow the active field
      dec: () => this.setField(a, this.val(S, a) - a.big), inc: () => this.setField(a, this.val(S, a) + a.big), lessAria: 'Less: ' + a.label, moreAria: 'More: ' + a.label,
      rMin: a.min, rMax: a.max, rStep: a.step, rVal: aVal, rLabel: a.label, onRange: e => this.setField(a, +e.target.value),
      // typing
